	private static class LimitedHistoryComboBoxModel : DefaultComboBoxModel<string> {

		private static readonly int MAX_SIZE = 10;

		/* @Override */
		public void addElement(string anObject) {
			int index = getIndexOf(anObject);
			if (index != -1) {
				// already here, move up in the list
				base.insertElementAt(anObject, 0);
				removeElementAt(index + 1);
				return;
			}

			base.insertElementAt(anObject, 0);
			enforceSize();
		}

		/* @Override */
		public void insertElementAt(string anObject, int index) {
			int currentIndex = getIndexOf(anObject);
			if (currentIndex != -1) {
				// already here, move up in the list
				base.insertElementAt(anObject, index);
				removeElementAt(currentIndex + 1);
				return;
			}

			base.insertElementAt(anObject, index);
			enforceSize();
		}

		private void enforceSize() {
			int size = getSize();
			if (size > MAX_SIZE) {
				removeElementAt(size - 1);
			}
		}
	}

